// === Tab: main.js ===
/*
Coronavirus simulation

Roughly simulates an outbreak using different social distances.
Play around with the variables at the top to explore how it can spread in different environments.

Inspired by this article:
https://www.washingtonpost.com/graphics/2020/world/corona-simulator/?fbclid=IwAR1tGUaApSRIXYCArDRx3kra6xkTNUkh4k4EWonp0d0XOvU2P9z7pVqiOcQ

Author:
  Jason Labbe

Original Sketch link:
	https://www.openprocessing.org/sketch/858150

Site:
  jasonlabbe3d.com
*/

var population = 150;
var personSize = 30;
var recoveryTime = 300;
var deathChance = 7; // Out of 100%
var socialDistance = 0; // Out of 100%

var _people = [];
var _collisions = true;

var _normalCount = 0;
var _sickCount = 0;
var _recoveryCount = 0;
var _deathCount = 0;
var _socialDistanceCount = 0;

var _normalEmoji = "😀";
var _sickEmoji = "🥵";
var _recoveryEmoji = "😎";
var _deadEmoji = "💀";

const NORMAL = 0;
const SICK = 1;
const RECOVER = 2;
const DEAD = 3;

function setup() {
	createCanvas(800, 600);
	textSize(personSize);

	resetSim();
}

function draw() {
	background(0);
	for (let i = 0; i < _people.length; i++) {
		_people[i].move();
		_people[i].display();
	}
}

function resetSim() {
	frameCount = 0;
	_people = [];
	_normalCount = population;
	_sickCount = 0;
	_recoveryCount = 0;
	_deathCount = 0;
	_socialDistanceCount = 0;

	for (let i = 0; i < population; i++) {
		let person = new Person(random(width), random(height));
		_people.push(person);

		if (i / population * 100 < socialDistance) {
			person.practiceSocialDistance();
		}
	}

	// Patient zero doesn't practice social distancing.
	for (let i = 0; i < _people.length; i++) {
		if (!_people[i].socialDistance) {
			_people[i].setState(SICK);
			break;
		}
	}
}

function keyPressed(){
	if(keyCode == 70){//f
		let fs = fullscreen();
    fullscreen(!fs);
		return;
	}else if(keyCode == 82){//r
		createCanvas(windowWidth, windowHeight);
		textSize(personSize);
		resetSim();
		return;
	}else if(keyCode == 49){//1
		//No social distance
		socialDistance = 0;
		resetSim();
	}else if(keyCode == 50){//2
		//Low social distance
		socialDistance = 30;
		resetSim();
	}else if(keyCode == 51){//3
		//High social distance
		socialDistance = 85;
		resetSim();
	}else if(keyCode == 52){//4
		//Disable collisions
		_collisions = !_collisions;
		resetSim();
	}
}

// === Tab: person.js ===
function Person(x, y) {
	this.pos = new p5.Vector(x, y);
	this.vel = p5.Vector.random2D();
	this.state = NORMAL;
	this.infectedTime = 0;
	this.socialDistance = false;

	this.move = function() {
		if (this.state == DEAD) {
			return;
		}

		this.pos.add(this.vel);
		this.keepInBounds();

		this.interactWithOthers();

		if (this.state == SICK) {
			this.tryToRecover();
		}
	}

	this.interactWithOthers = function() {
		for (let i = 0; i < _people.length; i++) {
			let other = _people[i];
			if (this == other || other.state == DEAD) {
				continue;
			}

			let diffX = other.pos.x - this.pos.x;
			let diffY = other.pos.y - this.pos.y;
			let d = diffX * diffX + diffY * diffY;
			//let d = dist(this.pos.x, this.pos.y, other.pos.x, other.pos.y);

			if (d < personSize * personSize) {
				if (this.state == SICK || other.state == SICK) {
					if (this.state == NORMAL) {
						this.setState(SICK);
					}

					if (other.state == NORMAL) {
						other.setState(SICK);
					}
				}

				if (_collisions && !this.socialDistance) {
					// Resolve direct collision.
					let newDirection = new p5.Vector(this.pos.x, this.pos.y);
					newDirection.sub(other.pos);
					newDirection.normalize();
					newDirection.mult(personSize - sqrt(d));
					this.pos.add(newDirection);

					// Bounce to new direction.
					newDirection.normalize();
					this.vel.add(newDirection);
					this.vel.normalize();
				}

				break;
			}
		}
	}

	this.tryToRecover = function() {
		if (frameCount > this.infectedTime + recoveryTime) {
			if (random() < deathChance / 100.0) {
				this.setState(DEAD);
			} else {
				this.setState(RECOVER);
			}
		}
	}

	this.keepInBounds = function() {
		let halfSize = personSize / 2;

		if (this.pos.x - halfSize < 0 || this.pos.x + halfSize > width) {
			this.vel.x *= -1;
			this.pos.x = constrain(this.pos.x, halfSize, width - halfSize);
		}

		if (this.pos.y - halfSize < 0 || this.pos.y + halfSize > height) {
			this.vel.y *= -1;
			this.pos.y = constrain(this.pos.y, halfSize, height - halfSize);
		}
	}

	this.display = function() {
		if (this.state == NORMAL) {
			text(_normalEmoji, this.pos.x-personSize/2, this.pos.y+personSize/2);
		} else if (this.state == SICK) {
			text(_sickEmoji, this.pos.x-personSize/2, this.pos.y+personSize/2);
		} else if (this.state == RECOVER) {
			text(_recoveryEmoji, this.pos.x-personSize/2, this.pos.y+personSize/2);
		} else if (this.state == DEAD) {
			text(_deadEmoji, this.pos.x-personSize/2, this.pos.y+personSize/2);
		}
	}

	this.setState = function(newState) {
		this.state = newState;

		if (newState == SICK) {
			this.infectedTime = frameCount;
			_normalCount --;
			_sickCount++;
		} else if (this.state == RECOVER) {
			_sickCount--;
			_recoveryCount++;
		} else if (this.state == DEAD) {
			_sickCount--;
			_deathCount++;
		}
	}

	this.practiceSocialDistance = function() {
		this.vel.mult(0);
		this.socialDistance = true;
		_socialDistanceCount++;
	}
}

